export function sampleArchive() {
  const now = new Date();
  const sessions = fromJSON(
    examples.map(([day, title, user, assistant], index) => {
      const date = new Date(now);
      date.setDate(now.getDate() - (29 - day));
      date.setHours(11, 0, 0, 0);
      return {
        id: 'demo-' + index,
        title,
        date: date.toISOString(),
        messages: [
          { role: 'user', content: user },
          { role: 'assistant', content: assistant },
        ],
      };
    }),
  ).map((session) => profileSession(session, true));
  const { groups, metrics } = cluster(sessions);
  return { sessions, groups, metrics, edits: {}, revision: 0 };
}
